{"type":"SearchReplace","EditsApplied":{"old_string":"","new_string":"/**
 * Checks that a mutation only points at records usable from this workspace.
 *
 * A row that exists in another organization is a tenant-scope violation.
 * A row that is missing, archived, deleted, in another project, or not a
 * current member is not found. Callers must run these checks before writing.
 */
import { eq } from "drizzle-orm";
import { assertOrgScope } from "@/lib/tenant";
import { comments, getDb, issues, labels } from "@/server/db";
import * as memberRepo from "@/server/repositories/member-repository";
import type { CommentId, IssueId, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import { NotFoundError } from "./_support";

export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId | null,
): Promise<void> {
  if (userId === null) return;

  const member = await memberRepo.findMember(orgId, userId);
  if (member === null || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
}

export async function assertWorkspaceLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  const db = getDb();
  for (const labelId of labelIds) {
    const row = db.select().from(labels).where(eq(labels.id, labelId)).get();
    if (!row) throw new NotFoundError("Label", labelId);
    assertOrgScope(actor, row.orgId as OrgId);
    if (row.orgId !== orgId) throw new NotFoundError("Label", labelId);
  }
}

/** A parent must be a live issue in the same project. */
export function assertParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): void {
  if (parentId === null) return;

  const row = getDb().select().from(issues).where(eq(issues.id, parentId)).get();
  if (!row) throw new NotFoundError("Issue", parentId);
  assertOrgScope(actor, row.orgId as OrgId);
  if (
    row.orgId !== orgId ||
    row.projectId !== projectId ||
    row.archivedAt !== null
  ) {
    throw new NotFoundError("Issue", parentId);
  }
}

/**
 * A reply must target a live top-level comment on the same issue.
 * Replies to replies, deleted comments, and comments on other issues are
 * not found. A comment owned by another organization is out of scope.
 */
export function assertReplyTarget(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId | null,
): void {
  if (parentId === null) return;

  const row = getDb()
    .select()
    .from(comments)
    .where(eq(comments.id, parentId))
    .get();
  if (!row) throw new NotFoundError("Comment", parentId);
  assertOrgScope(actor, row.orgId as OrgId);
  if (
    row.orgId !== orgId ||
    row.issueId !== issueId ||
    row.archivedAt !== null ||
    row.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
}
